#!/usr/bin/env python3
import json
import sys
from pathlib import Path


def main():
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} <directory>", file=sys.stderr)
        return 1

    directory = Path(sys.argv[1])
    if not directory.is_dir():
        print(f"error: not a directory: {directory}", file=sys.stderr)
        return 1

    try:
        summary_file = open("summary.json", "x")
    except FileExistsError:
        print("error: summary.json already exists", file=sys.stderr)
        return 1

    with summary_file:
        values = []
        for path in sorted(directory.glob("*.json")):
            if not path.is_file():
                continue
            try:
                with open(path) as f:
                    data = json.load(f)
            except (OSError, json.JSONDecodeError):
                continue
            if isinstance(data, dict) and "cost_usd" in data:
                values.append(data["cost_usd"])

        total = sum(values)
        mean = total / len(values) if values else 0

        json.dump({"total": total, "mean": mean}, summary_file)

    return 0


if __name__ == "__main__":
    sys.exit(main())
